import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"并发模式（Concurrent Patterns）","description":"","frontmatter":{},"headers":[],"relativePath":"concurrency/overview.md","filePath":"concurrency/overview.md","lastUpdated":1791018886000}`),a={name:`concurrency/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="并发模式-concurrent-patterns" tabindex="-1">并发模式（Concurrent Patterns） <a class="header-anchor" href="#并发模式-concurrent-patterns" aria-label="Permalink to “并发模式（Concurrent Patterns）”">​</a></h1><p>并发模式（Concurrent Patterns）主要解决在多线程或多进程环境中如何有效、安全地协调和管理并发任务的问题。它们帮助开发者编写在并发情况下能够正确运行、性能高效且易于维护的程序。具体来说，并发模式解决以下几个核心问题：</p><ol><li><strong>线程安全</strong>：确保在多线程环境中共享资源的安全访问，避免竞态条件（Race Conditions）、死锁（Deadlocks）等问题。</li><li><strong>任务分配与协调</strong>：有效分配和调度并发任务，确保系统资源的最佳利用，同时保证任务的正确执行顺序。</li><li><strong>性能优化</strong>：通过并发执行提高系统的吞吐量和响应速度，尽量减少锁争用和上下文切换开销。</li><li><strong>可维护性与可扩展性</strong>：通过抽象和封装并发处理逻辑，提高代码的可维护性和可扩展性，减少错误。</li><li><strong>常见模式</strong>：围绕上述问题，逐步发展出一组可在实践中复用的并发模式，本目录逐一给出详解。</li></ol><h3 id="本目录包含的模式" tabindex="-1">本目录包含的模式 <a class="header-anchor" href="#本目录包含的模式" aria-label="Permalink to “本目录包含的模式”">​</a></h3><ul><li><a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者模式</a>：用缓冲区解耦生产者与消费者线程，平衡速度差异。</li><li><a href="/hello-design-patterns/concurrency/semaphore">信号量模式</a>：用计数器控制对有限资源的并发访问数量。</li><li><a href="/hello-design-patterns/concurrency/future">Future 模式</a>：用一个占位对象表示异步任务将来的结果，按需获取。</li><li><a href="/hello-design-patterns/concurrency/active-object">主动对象模式</a>：把方法调用转为任务在独立线程中执行，调用与执行分离。</li><li><a href="/hello-design-patterns/concurrency/double-checked-locking">双重检查锁定模式</a>：首次检查后进入同步块再检查一次，兼顾惰性初始化与性能。</li><li><a href="/hello-design-patterns/concurrency/event-loop">事件循环模式</a>：单线程循环地等待并处理事件，避免多线程上下文切换开销。</li><li><a href="/hello-design-patterns/concurrency/reactor">反应器模式</a>：用同步事件多路复用器分发 I/O 事件，把分发与处理解耦。</li><li><a href="/hello-design-patterns/concurrency/proactor">主动器模式</a>：基于异步 I/O 的完成通知触发处理回调，与反应器相对应。</li><li><a href="/hello-design-patterns/concurrency/thread-pool">线程池模式</a>：固定一组工作线程从队列取任务，把创建开销与并发度一起管住。</li><li><a href="/hello-design-patterns/concurrency/read-write-lock">读写锁模式</a>：读锁共享、写锁独占，读多写少时把吞吐拉起来。</li><li><a href="/hello-design-patterns/concurrency/work-stealing">工作窃取模式</a>：每个线程一个本地队列，空闲线程去别人的队尾偷任务。</li></ul><h3 id="选用建议" tabindex="-1">选用建议 <a class="header-anchor" href="#选用建议" aria-label="Permalink to “选用建议”">​</a></h3><ul><li>多个线程写共享状态时，按读写比例选互斥锁或<a href="/hello-design-patterns/concurrency/read-write-lock">读写锁</a>；只有计数与标志位用原子变量更划算。</li><li>任务多且到达快时用<a href="/hello-design-patterns/concurrency/thread-pool">线程池</a>，记得队列要有界；CPU 密集分片交给<a href="/hello-design-patterns/concurrency/work-stealing">工作窃取</a>。</li><li>只需要延迟保存创建结果时用 Future；需要把整个方法调用异步化时用主动对象。</li><li>单线程事件驱动的服务端用事件循环或反应器；底层支持异步完成通知时用主动器。</li><li>惰性初始化务必配合正确的同步原语（volatile/atomic、互斥锁、sync.Once）避免数据竞争。</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};